@@ -1,6 +1,29 @@
 export type Query = Record<string, string | string[]>;
+
+function decodeComponent(part: string): string {
+  const spaced = part.replace(/\+/g, " ");
+  try {
+    return decodeURIComponent(spaced);
+  } catch {
+    return spaced;
+  }
+}

 /** Parse a URL query string. See README.md for the rules. */
 export function parseQuery(query: string): Query {
-  throw new Error("not implemented");
+  const body = query.startsWith("?") ? query.slice(1) : query;
+  const result: Query = {};
+  for (const pair of body.split("&")) {
+    if (pair === "") continue;
+    const equals = pair.indexOf("=");
+    const key = decodeComponent(equals === -1 ? pair : pair.slice(0, equals));
+    const value = decodeComponent(equals === -1 ? "" : pair.slice(equals + 1));
+    let next: string | string[] = value;
+    if (Object.hasOwn(result, key)) {
+      const previous = result[key];
+      next = Array.isArray(previous) ? [...previous, value] : [previous, value];
+    }
+    Object.defineProperty(result, key, { value: next, enumerable: true, writable: true, configurable: true });
+  }
+  return result;
 }
